"""用户登录模块。"""

import hashlib
import hmac

_SALT = "demo-salt"


def _hash_password(password):
    """对密码进行加盐 SHA-256 摘要。"""
    return hashlib.sha256((_SALT + password).encode("utf-8")).hexdigest()


USERS = {
    "alice": _hash_password("secret123"),
    "bob": _hash_password("password456"),
}


def verify_password(username, password):
    """校验用户名与密码是否匹配。

    密码不再以明文存储与比较，改为加盐摘要后使用固定时间比较，
    避免时序攻击，同时统一忽略用户名首尾空白与大小写差异。
    """
    expected = USERS.get(username.strip().lower())
    if expected is None:
        return False
    return hmac.compare_digest(expected, _hash_password(password))


def login(username, password):
    """登录入口，校验通过返回 True，否则返回 False。"""
